window.HOEREN_TESTS[1] = {"id":"wochenende-und-freizeit","name":"Wochenende und Freizeit","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Sebastian, hier ist Markus. Das Fußballtraining am Donnerstag fällt diese Woche aus — unser Trainer ist krank. Statt Fußball habe ich uns für das Schwimmtraining am Samstag angemeldet, das ist eine gute Vorbereitung. Tennis spielen wir nächste Woche wieder, da ist der Platz frei. Bis Samstag im Schwimmbad! Tschüss.","gender":"m","q":"Was machen Sebastian und Markus am Samstag?","opts":["Schwimmen.","Fußball.","Tennis."],"correct":0},{"transcript":"Und nun das Wochenend-Wetter. Am Freitag gibt es noch leichten Regen am Nachmittag, aber vom Abend an wird es trocken und kühler. Der Samstag wird der schönste Tag — sonnig, fast wolkenlos, bis zu 23 Grad. Am Sonntag ändert sich das Wetter komplett: Wolken, Wind und kurze Schauer am Vormittag. Wer eine Wanderung plant, sollte das am Samstag tun.","gender":"f","q":"Wann ist der beste Tag für eine Wanderung?","opts":["Am Samstag.","Am Freitag.","Am Sonntag."],"correct":0},{"transcript":"Hi Anna, hier ist Lukas. Hör mal, wegen meiner Geburtstagsparty am Samstag — der Termin bleibt, das ist klar. Aber die Adresse ändert sich. Wir feiern nicht bei mir zu Hause, sondern in der Kneipe ‚Zum Anker‘ in der Schiller-Straße. Übrigens treffen wir uns vorher um sechs im Café Mozart auf einen Kaffee, falls du Lust hast. Bring deinen Bruder mit!","gender":"m","q":"Wo findet die Party statt?","opts":["Bei Lukas zu Hause.","In der Kneipe ‚Zum Anker‘.","Im Café Mozart."],"correct":1},{"transcript":"Achtung an alle Reisenden auf Gleis 4. Die S-Bahn nach Bad Wildbad fällt heute aus. Bitte nehmen Sie ersatzweise die S-Bahn nach Pforzheim — von dort fährt jede halbe Stunde ein Bus weiter. Oder Sie können mit der Regionalbahn um 14 Uhr 30 von Gleis 9 fahren, die hält direkt in Bad Wildbad. Wir bitten um Ihr Verständnis.","gender":"f","q":"Wie kommen Reisende heute am schnellsten direkt nach Bad Wildbad?","opts":["Mit der S-Bahn von Gleis 4.","Mit der Regionalbahn von Gleis 9.","Mit S-Bahn nach Pforzheim und dann Bus."],"correct":1},{"transcript":"Liebe Sportfreunde, das Marathonrennen morgen am Sonntag startet um neun Uhr im Stadtpark. Bitte beachten Sie die Sperrungen in der Innenstadt: Die Hauptstraße ist von acht bis elf Uhr gesperrt. Zuschauer können am besten am Rathaus oder an der Brücke stehen — dort gibt es auch warme Getränke. Wir wünschen allen Läufern viel Erfolg!","gender":"m","q":"Wo sollen Zuschauer am besten stehen?","opts":["Im Stadtpark beim Start.","In der Hauptstraße.","Am Rathaus oder an der Brücke."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch zwischen Anna und Markus. Sie hören den Text einmal. Was macht Anna an welchem Tag? Wählen Sie für jeden Tag den passenden Buchstaben (a–i).","lines":[{"speaker":"Markus","gender":"m","text":"Hi Anna! Hast du diese Woche noch einen freien Abend für einen Kaffee?"},{"speaker":"Anna","gender":"f","text":"Hallo Markus! Fast jeder Tag hat schon einen festen Termin bei mir."},{"speaker":"Markus","gender":"m","text":"Dein Klavier liegt dir doch am Herzen. Wann ist der Unterricht diesmal?"},{"speaker":"Anna","gender":"f","text":"Den Klavierunterricht habe ich am Dienstag. Den verpasse ich seit drei Jahren nie."},{"speaker":"Markus","gender":"m","text":"Gehst du in dieser Woche auch noch ins Schwimmbad?"},{"speaker":"Anna","gender":"f","text":"Nein. Ins Schwimmbad gehe ich nicht. Das Wasser ist mir gerade zu kalt."},{"speaker":"Markus","gender":"m","text":"Deine Eltern wollten mit dir ausgehen. Wann habt ihr dafür Zeit?"},{"speaker":"Anna","gender":"f","text":"Mit meinen Eltern gehe ich am Mittwoch ins Theater. Wir sehen ein modernes Stück."},{"speaker":"Markus","gender":"m","text":"Triffst du Clara noch zum gemeinsamen Kochen?"},{"speaker":"Anna","gender":"f","text":"Ja. Mit Clara koche ich am Donnerstag italienisch. Wir machen zusammen Pasta."},{"speaker":"Markus","gender":"m","text":"Steht der Sport mit Robert von der Arbeit auch noch?"},{"speaker":"Anna","gender":"f","text":"Tennis spiele ich mit Robert am Freitag. Das ist unser fester Termin seit dem Frühjahr."},{"speaker":"Markus","gender":"m","text":"Spielst du auch Fußball wie dein Bruder?"},{"speaker":"Anna","gender":"f","text":"Nein. Fußball spiele ich nicht. Das macht nur mein Bruder."},{"speaker":"Markus","gender":"m","text":"Dann bleibt nur noch der große Tag mit deiner Familie."},{"speaker":"Anna","gender":"f","text":"Die Hochzeit meiner Schwester Lisa besuche ich am Samstag. Die ganze Familie kommt."},{"speaker":"Markus","gender":"m","text":"Das wird sicher ein langer und schöner Tag. Den Kaffee holen wir ein anderes Mal."}],"options":[{"letter":"a","text":"ins Schwimmbad gehen"},{"letter":"b","text":"Fußball spielen"},{"letter":"c","text":"Hochzeit besuchen"},{"letter":"d","text":"Buch zu Hause lesen"},{"letter":"e","text":"Theater mit den Eltern"},{"letter":"f","text":"Tennis mit Robert"},{"letter":"g","text":"ins Kino gehen"},{"letter":"h","text":"gemeinsam mit Clara kochen"},{"letter":"i","text":"Klavierunterricht"}],"items":[{"person":"Dienstag","correct":"i"},{"person":"Mittwoch","correct":"e"},{"person":"Donnerstag","correct":"h"},{"person":"Freitag","correct":"f"},{"person":"Samstag","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Guten Tag, kann ich helfen?"},{"speaker":"Kunde","gender":"m","text":"Ja, ich möchte mich für einen Sportkurs anmelden."},{"speaker":"Mitarbeiterin","gender":"f","text":"Welchen denn? Wir haben Yoga am Montagabend, Schwimmen am Dienstag und Pilates ab nächster Woche am Freitag."},{"speaker":"Kunde","gender":"m","text":"Yoga klingt gut, aber Montag passt mir gar nicht."},{"speaker":"Mitarbeiterin","gender":"f","text":"Dann Schwimmen oder Pilates? Pilates startet erst nächste Woche."},{"speaker":"Kunde","gender":"m","text":"Ich will diese Woche schon anfangen. Dann nehme ich Schwimmen."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gerne, acht Wochen für 80 Euro."}],"q":"Für welchen Kurs meldet sich der Kunde an?","opts":["Schwimmen.","Yoga.","Pilates."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Sollen wir noch was essen? Ich habe Hunger nach dem Film."},{"speaker":"Frau","gender":"f","text":"Klar, italienisch oder griechisch?"},{"speaker":"Mann","gender":"m","text":"Im italienischen Restaurant war ich erst am Freitag. Heute lieber griechisch."},{"speaker":"Frau","gender":"f","text":"Bei Sokrates ist es gut, aber sehr teuer."},{"speaker":"Mann","gender":"m","text":"Stimmt, bei Olympia ist es billiger und das Essen ist auch lecker."},{"speaker":"Frau","gender":"f","text":"Okay, Olympia. Wie kommen wir hin?"},{"speaker":"Mann","gender":"m","text":"Mit dem Bus, nur 5 Minuten."}],"q":"In welches Restaurant gehen sie?","opts":["Restaurant Olympia.","Restaurant Sokrates.","Italienisches Restaurant."],"correct":0},{"lines":[{"speaker":"Sekretärin","gender":"f","text":"Praxis Dr. Vogel, guten Tag."},{"speaker":"Patient","gender":"m","text":"Hallo, ich möchte einen Termin für meine Mutter."},{"speaker":"Sekretärin","gender":"f","text":"Wir haben Dienstag um 9, Mittwoch um 14 oder Donnerstag um 11 Uhr frei."},{"speaker":"Patient","gender":"m","text":"Mittwoch wäre gut, aber leider hat meine Mutter da schon einen anderen Termin."},{"speaker":"Sekretärin","gender":"f","text":"Dann Dienstag oder Donnerstag?"},{"speaker":"Patient","gender":"m","text":"Donnerstag um 11. Meine Mutter ist da fitter als am Morgen."},{"speaker":"Sekretärin","gender":"f","text":"Notiert, bis Donnerstag."}],"q":"Wann ist der Termin?","opts":["Dienstag um 9 Uhr.","Donnerstag um 11 Uhr.","Mittwoch um 14 Uhr."],"correct":1},{"lines":[{"speaker":"Tochter","gender":"f","text":"Was kaufen wir für Papa zum Geburtstag?"},{"speaker":"Sohn","gender":"m","text":"Ein Buch über Geschichte? Er liest gern."},{"speaker":"Tochter","gender":"f","text":"Bücher hat er schon viele. Wie wäre es mit einer schönen Tasse?"},{"speaker":"Sohn","gender":"m","text":"Eine Tasse hatten wir letztes Jahr. Was ist mit einem Schal? Es wird bald kalt."},{"speaker":"Tochter","gender":"f","text":"Gute Idee! Wo kaufen wir den?"},{"speaker":"Sohn","gender":"m","text":"Im Kaufhaus Brückner, da habe ich neulich schöne gesehen."}],"q":"Was kaufen sie für ihren Vater?","opts":["Ein Buch.","Eine Tasse.","Einen Schal."],"correct":2},{"lines":[{"speaker":"Rezeption","gender":"f","text":"Hotel Stern, guten Tag."},{"speaker":"Gast","gender":"m","text":"Hallo, ich brauche ein Zimmer für drei Nächte ab Freitag."},{"speaker":"Rezeption","gender":"f","text":"Einzelzimmer oder Doppelzimmer?"},{"speaker":"Gast","gender":"m","text":"Doppelzimmer. Aber gibt es auch ein Familienzimmer? Mein Sohn kommt vielleicht mit."},{"speaker":"Rezeption","gender":"f","text":"Doppelzimmer ist 240 Euro für drei Nächte. Familienzimmer 290 Euro. Aber das ist sicherer, falls Ihr Sohn doch kommt."},{"speaker":"Gast","gender":"m","text":"Stimmt, dann nehme ich das Familienzimmer."}],"q":"Welches Zimmer reserviert der Gast?","opts":["Einzelzimmer.","Doppelzimmer.","Familienzimmer."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Hartmann, einer Yoga-Lehrerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Hartmann, Sie unterrichten Yoga in Ihrem eigenen Studio. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Hartmann","gender":"f","text":"Eigentlich bin ich Lehrerin für Englisch und Spanisch. Ich habe lange in einer Schule gearbeitet, fast zehn Jahre. Aber ich hatte oft Rückenschmerzen und habe angefangen, Yoga zu machen. Das hat mir so gut geholfen, dass ich eine Ausbildung gemacht habe — nebenbei, abends nach der Arbeit."},{"speaker":"Reporter","gender":"m","text":"Und wann haben Sie den Schulberuf aufgegeben?"},{"speaker":"Hartmann","gender":"f","text":"Vor zwei Jahren. Ich habe mich entschieden, ganz auf Yoga umzusteigen. Mein eigenes Studio habe ich vor einem Jahr eröffnet. Es war ein großes Risiko, aber bisher läuft alles gut."},{"speaker":"Reporter","gender":"m","text":"Wie sind Ihre Arbeitszeiten?"},{"speaker":"Hartmann","gender":"f","text":"Sehr anders als in der Schule. Kurse morgens vor der Arbeit, abends nach der Arbeit, und am Wochenende. Die meisten Schüler kommen außerhalb der Arbeitszeit. Mittags ist es ruhig — das ist meine eigene Zeit für Verwaltung und Übungen."},{"speaker":"Reporter","gender":"m","text":"Wer sind Ihre typischen Schüler?"},{"speaker":"Hartmann","gender":"f","text":"Verschiedene Menschen. Viele Frauen, aber auch Männer. Junge und alte. Die meisten kommen wegen Stress oder Rückenschmerzen, genau wie ich damals."},{"speaker":"Reporter","gender":"m","text":"Ihr Studio bietet auch besondere Kurse an, oder?"},{"speaker":"Hartmann","gender":"f","text":"Ja, ich habe einen Kurs nur für Senioren — sehr ruhig und sanft. Und einen für Schwangere. Babys nehme ich noch nicht, das überlege ich aber."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie selbst, um fit zu bleiben?"},{"speaker":"Hartmann","gender":"f","text":"Yoga jeden Tag, aber nur 30 Minuten. Außerdem fahre ich Fahrrad zur Arbeit, das sind 6 Kilometer. Joggen mag ich überhaupt nicht — das ist mir zu hart für die Knie."}],"items":[{"q":"Sie hat ihr eigenes Yoga-Studio.","correct":"ja"},{"q":"Frau Hartmann war früher Sportlehrerin.","correct":"nein"},{"q":"Mittags hat sie die meisten Kurse.","correct":"nein"},{"q":"Sie unterrichtet auch ältere Menschen.","correct":"ja"},{"q":"Sie geht regelmäßig joggen.","correct":"nein"}]}]};
